package routing

import (
	_ "embed"
	"net/netip"
	"strings"
	"sync"
)

// ir_ipv4.txt is generated by backend/tools/ir-cidrs from RIPE NCC's delegation file;
// its header records the source and date. Embedded (not fetched at runtime) so a panel
// with no outbound internet - common for installs inside Iran - renders the same
// configs, and so a config never depends on a third party being up.
//
//go:embed ir_ipv4.txt
var irIPv4Raw string

var (
	irOnce     sync.Once
	irPrefixes []netip.Prefix
)

// IranIPv4 returns the aggregated Iranian IPv4 CIDRs (sorted, non-overlapping). The
// slice is shared: callers must not modify it.
func IranIPv4() []netip.Prefix {
	irOnce.Do(func() {
		var lines []string
		for _, l := range strings.Split(irIPv4Raw, "\n") {
			l = strings.TrimSpace(l)
			if l == "" || strings.HasPrefix(l, "#") {
				continue
			}
			lines = append(lines, l)
		}
		ps, err := ParseIPv4CIDRs(lines)
		if err != nil {
			// The file is generated and tested; a parse failure is a build-time bug.
			panic("routing: embedded ir_ipv4.txt is malformed: " + err.Error())
		}
		irPrefixes = Aggregate(ps)
	})
	return irPrefixes
}

// IranListHeader returns the "# ..." comment header of the embedded list (source and
// dates), for display in the admin UI/API docs.
func IranListHeader() string {
	var out []string
	for _, l := range strings.Split(irIPv4Raw, "\n") {
		if !strings.HasPrefix(l, "#") {
			break
		}
		out = append(out, strings.TrimSpace(strings.TrimPrefix(l, "#")))
	}
	return strings.Join(out, "\n")
}

// PrivateIPv4 are the LAN / non-routable ranges every bypass mode keeps off the
// tunnel: sending a client's own router, printer or CGNAT-internal traffic to a remote
// node can only break things.
func PrivateIPv4() []netip.Prefix {
	return []netip.Prefix{
		netip.MustParsePrefix("10.0.0.0/8"),
		netip.MustParsePrefix("172.16.0.0/12"),
		netip.MustParsePrefix("192.168.0.0/16"),
		netip.MustParsePrefix("169.254.0.0/16"),
		netip.MustParsePrefix("100.64.0.0/10"),
		netip.MustParsePrefix("127.0.0.0/8"),
	}
}
